    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    color = next(v for v in set(v for row in grid for v in row) if v != bg)

    colored_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    # Separate the repeated shapes into vertically distinct groups.
    groups = []
    for r in colored_rows:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)

    if len(groups) >= 2:
        first, second = groups[0], groups[1]
        shift = second[0] - first[0]
        for r in second:
            source_r = r - shift
            if source_r in first:
                for c in range(w):
                    if grid[source_r][c] != bg and grid[r][c] == bg:
                        out[r][c] = 1
    return out
